export default function AuthBackground({ children }: { children: ReactNode }) {
  return (
    <div
      className="relative min-h-screen w-full overflow-hidden"
      style={{ background: "linear-gradient(180deg,#eef8f1 0%,#dcefe3 55%,#e9f5ec 100%)" }}
    >
      <style>{FONTS}</style>

      {/* soft mist */}
      <div className="pointer-events-none absolute inset-0" dangerouslySetInnerHTML={{ __html: MIST }} />

      {/* heritage skyline */}
      <div
        className="pointer-events-none absolute bottom-0 left-0 h-[38vh] min-h-[200px] w-full"
        dangerouslySetInnerHTML={{ __html: SKYLINE }}
      />

      {/* leaves: top-right and bottom-right */}
      <div
        className="pointer-events-none absolute right-0 top-0 w-[min(22vw,300px)] min-w-[130px]"
        dangerouslySetInnerHTML={{ __html: LEAVES }}
      />
      <div
        className="pointer-events-none absolute bottom-0 right-0 w-[min(22vw,300px)] min-w-[130px]"
        style={{ transform: "scaleY(-1)" }}
        dangerouslySetInnerHTML={{ __html: LEAVES }}
      />

      {/* form row: art panel is now a real flex item sized by aspect-ratio,
          not an absolutely-positioned 100vh block. This guarantees its full
          height -- top (logo) to bottom (compass) -- always renders, since
          it stretches to match whatever height this flex row actually is,
          rather than assuming that height equals 100vh exactly. */}
      <div className="relative z-10 flex min-h-screen">
        <div
          className="pointer-events-none hidden shrink-0 self-stretch lg:block"
          style={{ aspectRatio: "460 / 860" }}
          dangerouslySetInnerHTML={{ __html: ART }}
        />
        <div className="flex flex-1 items-center justify-center px-5 py-10">
          <div className="flex w-full flex-col items-center">
            {/* small logo for phones/tablets */}
            <div className="mb-6 flex items-center gap-2 lg:hidden">
              <span className="flex h-9 w-9 items-center justify-center rounded-full bg-emerald-800">
                <span className="h-4 w-4 rounded-full bg-emerald-50" />
              </span>
              <div className="leading-tight">
                <p className="text-2xl font-extrabold text-emerald-900">Questination</p>
                <p className="text-xs font-medium text-emerald-900">Vocal for Local</p>
              </div>
            </div>
            {children}
          </div>
        </div>
      </div>
    </div>
  );
}
